The triangles are similar. Write a similarity statement, list the corresponding sides and name the angle corresponding to $\angle BCA$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (A) at (0,1.8);
\coordinate (B) at (3.118,1.8);
\coordinate (C) at (0,0);
\draw (A)--(B)--(C)--cycle;
\draw (0,1.55)--(0.25,1.55)--(0.25,1.8);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[below] at (C) {$C$};
\node at (0.38,0.65) {$60^{\circ}$};
\coordinate (D) at (4.5,0);
\coordinate (E) at (4.5,2.7);
\coordinate (F) at (9.177,0);
\draw (D)--(E)--(F)--cycle;
\draw (4.5,0.25)--(4.75,0.25)--(4.75,0);
\node[below left] at (D) {$D$};
\node[above] at (E) {$E$};
\node[below right] at (F) {$F$};
\node at (4.88,2.05) {$60^{\circ}$};
\end{tikzpicture}
[/tikz]

The triangles are similar. Matching arc marks indicate equal angles. Write a similarity statement and name the side corresponding to $JK$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\usetikzlibrary{angles}
\coordinate (J) at (0,0);
\coordinate (K) at (2.4,0);
\coordinate (L) at (0.7,1.8);
\coordinate (R) at (7,0);
\coordinate (S) at (3.88,0);
\coordinate (T) at (6.09,2.34);
\draw (J)--(K)--(L)--cycle;
\draw (R)--(S)--(T)--cycle;
\pic[draw,angle radius=0.3cm] {angle=K--J--L};
\pic[draw,angle radius=0.3cm] {angle=L--K--J};
\pic[draw,angle radius=0.4cm] {angle=L--K--J};
\pic[draw,angle radius=0.3cm] {angle=T--R--S};
\pic[draw,angle radius=0.3cm] {angle=R--S--T};
\pic[draw,angle radius=0.4cm] {angle=R--S--T};
\node[below left] at (J) {$J$};
\node[below right] at (K) {$K$};
\node[above] at (L) {$L$};
\node[below right] at (R) {$R$};
\node[below left] at (S) {$S$};
\node[above] at (T) {$T$};
\end{tikzpicture}
[/tikz]

The pentagons are similar; the second is reflected. Write a similarity statement, name the side corresponding to $CD$ and name the angle corresponding to $\angle EAB$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (A) at (0,1.4);
\coordinate (B) at (0.6,2);
\coordinate (C) at (3,2);
\coordinate (D) at (3,0);
\coordinate (E) at (0,0);
\draw (A)--(B)--(C)--(D)--(E)--cycle;
\node[left] at (A) {$A$};
\node[above] at (B) {$B$};
\node[above right] at (C) {$C$};
\node[below right] at (D) {$D$};
\node[below left] at (E) {$E$};
\coordinate (P) at (7,0.98);
\coordinate (Q) at (6.58,1.4);
\coordinate (R) at (4.9,1.4);
\coordinate (S) at (4.9,0);
\coordinate (T) at (7,0);
\draw (P)--(Q)--(R)--(S)--(T)--cycle;
\node[right] at (P) {$P$};
\node[above] at (Q) {$Q$};
\node[above left] at (R) {$R$};
\node[below left] at (S) {$S$};
\node[below right] at (T) {$T$};
\end{tikzpicture}
[/tikz]

The intervals $KP$ and $LQ$ intersect at $O$, and $KL\parallel PQ$. Triangles $KOL$ and $POQ$ are similar. Write a similarity statement and list the corresponding sides.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (K) at (-1.8,1.2);
\coordinate (L) at (-1.8,-1.2);
\coordinate (O) at (0,0);
\coordinate (P) at (2.7,-1.8);
\coordinate (Q) at (2.7,1.8);
\draw (K)--(P);
\draw (L)--(Q);
\draw (K)--(L);
\draw (P)--(Q);
\draw[->] (-1.8,0.3)--(-1.8,-0.3);
\draw[->] (2.7,0.3)--(2.7,-0.3);
\node[above left] at (K) {$K$};
\node[below left] at (L) {$L$};
\node[above] at (O) {$O$};
\node[below right] at (P) {$P$};
\node[above right] at (Q) {$Q$};
\end{tikzpicture}
[/tikz]

In the diagram, $GH\parallel EF$. Triangles $DGH$ and $DEF$ are similar. Write a similarity statement and name the side corresponding to $GH$.
[tikz]
\begin{tikzpicture}[draw=black,text=black,every node/.style={font=\fontsize{10}{12}\selectfont}]
\coordinate (D) at (1.2,3);
\coordinate (E) at (0,0);
\coordinate (F) at (4,0);
\coordinate (G) at (0.6,1.5);
\coordinate (H) at (2.6,1.5);
\draw (D)--(E)--(F)--cycle;
\draw (G)--(H);
\draw[->] (1.3,1.5)--(1.8,1.5);
\draw[->] (1.6,0)--(2.1,0);
\node[above] at (D) {$D$};
\node[below left] at (E) {$E$};
\node[below right] at (F) {$F$};
\node[left] at (G) {$G$};
\node[right] at (H) {$H$};
\end{tikzpicture}
[/tikz]
